(function(){var e=document.documentElement,a=document.querySelector(".theme");if(a){var r=function(){a.setAttribute("aria-pressed",e.getAttribute("data-theme")==="dark"?"true":"false")};r(),a.addEventListener("click",function(){var t=e.getAttribute("data-theme")==="dark"?"light":"dark";e.setAttribute("data-theme",t);try{localStorage.setItem("theme",t)}catch{}r()})}document.querySelectorAll(".lang a[hreflang]").forEach(function(t){t.addEventListener("click",function(){try{localStorage.setItem("lang",t.getAttribute("hreflang"))}catch{}})})})();
